      g.fill();
    }
    const grd = g.createRadialGradient(cx, cy, 4, cx, cy, 150);
    grd.addColorStop(0, 'rgba(95,5,5,0.75)');
    grd.addColorStop(1, 'rgba(80,3,3,0)');
    g.fillStyle = grd;
    g.beginPath();
    g.arc(cx, cy, 150, 0, Math.PI * 2);
    g.fill();
  }, 1, 1, renderer);
  blood.wrapS = blood.wrapT = THREE.ClampToEdgeWrapping;

  const door = createCanvasTexture(256, (g, S) => {
    g.fillStyle = '#5b635b';
    g.fillRect(0, 0, S, S);
    g.strokeStyle = 'rgba(28,32,28,0.9)';
    g.lineWidth = 10;
    g.strokeRect(16, 16, S - 32, S - 32);
    g.strokeStyle = 'rgba(170,176,160,0.22)';
    g.lineWidth = 2;
    g.strokeRect(32, 32, S - 64, S - 64);
    g.fillStyle = 'rgba(40,45,40,0.5)';
    g.fillRect(58, 74, S - 116, 60);
    stains(g, S, 24, '30,24,14', 40, 0.3);
    noiseOverlay(g, S, 20);
  }, 1, 1, renderer);

  const glow = makeGlowTexture();

  const mats = {
    wall: new THREE.MeshStandardMaterial({ map: wall, color: 0xb9b9ab, roughness: 0.94, metalness: 0.03 }),
    floor: new THREE.MeshStandardMaterial({ map: floor, color: 0x9fa096, roughness: 0.9, metalness: 0.06 }),
    ceiling: new THREE.MeshStandardMaterial({ map: ceiling, color: 0xa9a99c, roughness: 0.96, metalness: 0.02 }),
    fabric: new THREE.MeshStandardMaterial({ map: fabric, color: 0xb9b4a2, roughness: 0.98 }),
    metal: new THREE.MeshStandardMaterial({ map: metal, color: 0x9fa39c, roughness: 0.56, metalness: 0.6 }),
    metalDark: new THREE.MeshStandardMaterial({ color: 0x313531, roughness: 0.62, metalness: 0.55 }),
    mattress: new THREE.MeshStandardMaterial({ map: fabric, color: 0x99978a, roughness: 1 }),
    sheet: new THREE.MeshStandardMaterial({ color: 0xb8b3a2, roughness: 0.97 }),
    door: new THREE.MeshStandardMaterial({ map: door, color: 0x8b9287, roughness: 0.68, metalness: 0.3 }),
    blood: new THREE.MeshStandardMaterial({
      map: blood, color: 0x8f1717, transparent: true, roughness: 0.55,
      depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2,
    }),
    bone: new THREE.MeshStandardMaterial({ color: 0xd2c8ab, roughness: 0.58, metalness: 0.02 }),
    skin: new THREE.MeshStandardMaterial({
      map: skin, color: 0x9c8b72, roughness: 0.88, metalness: 0.02,
      emissive: 0x0b0704, emissiveIntensity: 0.85,
    }),
    robe: new THREE.MeshStandardMaterial({ map: robe, color: 0x333333, roughness: 0.97 }),
    black: new THREE.MeshBasicMaterial({ color: 0x000000 }),
    eye: new THREE.MeshBasicMaterial({ color: 0xffd23a, toneMapped: false }),
    exitRed: new THREE.MeshStandardMaterial({
      color: 0x230606, emissive: 0x8f0d0d, emissiveIntensity: 1.25, roughness: 0.55, metalness: 0.45,
    }),
    exitGreen: new THREE.MeshStandardMaterial({
      color: 0x04140a, emissive: 0x17c25c, emissiveIntensity: 1.5, roughness: 0.5, metalness: 0.35,
    }),
    porcelain: new THREE.MeshStandardMaterial({ color: 0xbcbcb0, roughness: 0.32, metalness: 0.05 }),
  };

  return { tex: { wall, floor, ceiling, fabric, metal, skin, robe, blood, door }, glow, mats };
}

import { clamp, lerp } from './config.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuf = null;
    this.muted = false;
    this.started = false;
    this.threat = 0;
    this.heartTimer = 0;
    this.soulTimer = 0;
    this.soulPing = 0;
  }

  init() {
    if (this.started) {
      if (this.ctx?.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      const ctx = new AC();
      this.ctx = ctx;
      this.started = true;
      this.master = ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.52;
      this.master.connect(ctx.destination);

      // sub drone
      const droneGain = ctx.createGain();
      droneGain.gain.value = 0.055;
      droneGain.connect(this.master);
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 150;
      lp.Q.value = 1.2;
      lp.connect(droneGain);
      this.droneFilter = lp;
      [41, 55, 82.4].forEach((f, i) => {
        const o = ctx.createOscillator();
        o.type = i === 2 ? 'triangle' : 'sine';
        o.frequency.value = f;
        const g = ctx.createGain();
        g.gain.value = i === 2 ? 0.14 : 0.45;
        o.connect(g);
        g.connect(lp);
        o.start();
        if (i === 0) {
          const lfo = ctx.createOscillator();
          lfo.frequency.value = 0.07;
          const lg = ctx.createGain();
          lg.gain.value = 1.6;
          lfo.connect(lg);
          lg.connect(o.frequency);
          lfo.start();
        }
      });

      // air / room tone
      const len = Math.floor(ctx.sampleRate * 2);
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * 0.35;
      this.noiseBuf = buf;
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.loop = true;
      const bp = ctx.createBiquadFilter();
      bp.type = 'bandpass';
      bp.frequency.value = 380;
      bp.Q.value = 0.45;
      const ng = ctx.createGain();
      ng.gain.value = 0.02;
      src.connect(bp);
      bp.connect(ng);
      ng.connect(this.master);
      src.start();
      this.airGain = ng;
    } catch {
      this.ctx = null;
      this.started = false;
    }
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.52, this.ctx.currentTime, 0.08);
    }
  }

  _noise(duration, gain, filterType, freq, when = 0, q = 1) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter();
    f.type = filterType;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.05);
  }

  _tone(freq, duration, gain, type = 'sine', when = 0, endFreq = 0) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (endFreq) o.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    o.connect(g);
    g.connect(this.master);
    o.start(t);
    o.stop(t + duration + 0.05);
  }

  footstep(running) {
    if (!this.ctx || this.muted) return;
    const g = running ? 0.11 : 0.065;
    this._noise(running ? 0.16 : 0.12, g, 'lowpass', running ? 420 : 300, 0, 0.6);
    this._tone(running ? 82 : 68, 0.1, g * 0.55, 'sine');
  }

  pickup() {
    if (!this.ctx || this.muted) return;
    this._tone(523, 0.5, 0.12, 'sine', 0);
    this._tone(784, 0.6, 0.09, 'sine', 0.08);
    this._tone(1046, 0.7, 0.06, 'sine', 0.16);
    this._noise(0.4, 0.035, 'highpass', 2200, 0.02);
  }

  heartbeat(intensity) {
    if (!this.ctx || this.muted) return;
    this._tone(52, 0.16, 0.14 + intensity * 0.18, 'sine');
    this._tone(44, 0.2, 0.1 + intensity * 0.12, 'sine', 0.19);
  }

  growl() {
    if (!this.ctx || this.muted) return;
    this._tone(64, 0.85, 0.09, 'sawtooth', 0, 46);
    this._noise(0.7, 0.045, 'bandpass', 210, 0, 2.5);
  }

  whisper() {
    if (!this.ctx || this.muted) return;
    this._noise(0.55, 0.03, 'bandpass', 1500 + Math.random() * 900, 0, 3);
  }

  scare() {
    if (!this.ctx) return;
    this._noise(1.1, 0.55, 'highpass', 600, 0, 0.7);
    this._tone(920, 1.1, 0.16, 'sawtooth', 0, 120);
    this._tone(140, 1.3, 0.24, 'sawtooth', 0, 32);
    this._tone(57, 1.4, 0.3, 'sine', 0, 28);
    this._noise(1.5, 0.2, 'lowpass', 240, 0.25, 1);
  }

  exitChime() {
    if (!this.ctx || this.muted) return;
    [392, 523, 659, 784].forEach((f, i) => this._tone(f, 0.9, 0.08, 'sine', i * 0.11));
  }

  soulClose(distance) {
    if (!this.ctx || this.muted) return;
    this._tone(220 + (10 - Math.min(distance, 10)) * 30, 0.35, 0.025, 'sine', 0, 300);
  }

  update(dt, threat, playing, soulsNear = 99) {
    if (!this.ctx) return;
    this.threat = lerp(this.threat, threat, 0.12);
    if (this.droneFilter) this.droneFilter.frequency.value = 130 + this.threat * 320;
    if (this.airGain) this.airGain.gain.value = 0.018 + this.threat * 0.02;
    if (!playing || this.muted) return;

    this.heartTimer -= dt;
    if (this.threat > 0.16 && this.heartTimer <= 0) {
      this.heartbeat(clamp(this.threat, 0, 1));
      this.heartTimer = lerp(1.5, 0.36, this.threat);
    }
    this.soulTimer -= dt;
    if (soulsNear < 11 && this.soulTimer <= 0) {
      this.soulClose(soulsNear);
      this.soulTimer = lerp(2.4, 1.5, 1 - soulsNear / 11);
    }
  }
}

import * as THREE from '../vendor/three.module.js';
import { CONFIG, rand, randInt, pick, shuffle } from './config.js';
import { makeSign } from './textures.js';

const { mapW: W, mapH: H, cell: CELL, wallH: WALL_H } = CONFIG;

const SIGN_WORDS = [
  ['WARD 3', '#a8e8b8'], ['MORGUE', '#e8a8a8'], ['X-RAY', '#a8d8e8'],
  ['NO ENTRY', '#e8c58a'], ['ICU', '#a8e8b8'], ['STAFF ONLY', '#d8d8c0'],
  ['ELEVATOR', '#c0c8a8'], ['PHARMACY', '#a8e8c8'],
];

export class HospitalWorld {
  constructor(scene, assets) {
    this.scene = scene;
    this.assets = assets;
    this.group = null;
    this.souls = [];
    this.colliders = [];
    this.fixtures = [];
    this.exit = null;
    this.exitActive = false;
    this.dust = null;
    this.grid = null;
    this.openCells = [];
  }

  cellCenter(x, y, out = new THREE.Vector3()) {
    return out.set((x - (W - 1) / 2) * CELL, 0, (y - (H - 1) / 2) * CELL);
  }

  cellOf(x, z) {
    return [Math.floor(x / CELL + W / 2), Math.floor(z / CELL + H / 2)];
  }

  isWall(x, y) {
    return x < 0 || y < 0 || x >= W || y >= H || this.grid[y][x] === 1;
  }

  canStand(x, z, radius = CONFIG.playerRadius, ignoreProps = false) {
    const [cx, cy] = this.cellOf(x, z);
    if (this.isWall(cx, cy)) return false;
    const steps = 8;
    for (let i = 0; i < steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const px = x + Math.cos(a) * radius;
      const pz = z + Math.sin(a) * radius;
      const [gx, gy] = this.cellOf(px, pz);
      if (this.isWall(gx, gy)) return false;
    }
    if (!ignoreProps) {
      for (const c of this.colliders) {
        const dx = x - c.x;
        const dz = z - c.z;
        if (dx * dx + dz * dz < (radius + c.r) * (radius + c.r)) return false;
      }
    }
    return true;
  }

  lineOfSight(a, b) {
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const dist = Math.hypot(dx, dz);
    const steps = Math.max(2, Math.ceil(dist / 0.32));
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      const [gx, gy] = this.cellOf(a.x + dx * t, a.z + dz * t);
      if (this.isWall(gx, gy)) return false;
    }
    return true;
  }

  bfs(start, goal) {
    if (!start || !goal) return null;
    const sk = start[1] * W + start[0];
    const gk = goal[1] * W + goal[0];
    if (this.grid[start[1]]?.[start[0]] === 1) return null;
    const prev = new Int32Array(W * H).fill(-1);
    const seen = new Uint8Array(W * H);
    const queue = [sk];
    seen[sk] = 1;
    let head = 0;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    while (head < queue.length) {
      const key = queue[head++];
      if (key === gk) break;
      const x = key % W;
      const y = (key - x) / W;
      for (const [dx, dy] of dirs) {
        const nx = x + dx;
        const ny = y + dy;
        if (this.isWall(nx, ny)) continue;
        const nk = ny * W + nx;
        if (seen[nk]) continue;
        seen[nk] = 1;
        prev[nk] = key;
        queue.push(nk);
      }
    }
    if (!seen[gk]) return null;
    const path = [];
    let k = gk;
    while (k !== -1) {
      path.push([k % W, Math.floor(k / W)]);
      if (k === sk) break;
      k = prev[k];
    }
    return path.reverse();
  }

  distanceField(start) {
    const dist = new Int32Array(W * H).fill(-1);
    const sk = start[1] * W + start[0];
    const queue = [sk];
    dist[sk] = 0;
    let head = 0;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    while (head < queue.length) {
      const key = queue[head++];
      const x = key % W;
      const y = (key - x) / W;
      for (const [dx, dy] of dirs) {
        const nx = x + dx;
        const ny = y + dy;
        if (this.isWall(nx, ny)) continue;
        const nk = ny * W + nx;
        if (dist[nk] !== -1) continue;
        dist[nk] = dist[key] + 1;
        queue.push(nk);
      }
    }
    return dist;
  }

  generate() {
    if (this.group) {
      this.scene.remove(this.group);
      this.group.traverse((o) => {
        if (o.isMesh && o.geometry) o.geometry.dispose();
      });
    }
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.souls = [];
    this.colliders = [];
    this.fixtures = [];
    this.exitActive = false;
    this.grid = this._maze();
    this.openCells = [];
    for (let y = 1; y < H - 1; y++) {
      for (let x = 1; x < W - 1; x++) {
        if (this.grid[y][x] === 0) this.openCells.push([x, y]);
      }
    }

    const layout = this._layout();
    this.spawn = layout.spawn;
    this.exitCell = layout.exitCell;

    this._buildShell();
    this._buildProps(layout);
    this._buildFixtures(layout);
    this._buildSigns();
    this._buildDecals();
    this._buildExit(layout);
    this._buildSouls(layout);
    this._buildDust();

    return layout;
  }

  _maze() {
    const g = Array.from({ length: H }, () => Array(W).fill(1));
    let x = 1;
    let y = 1;
    g[y][x] = 0;
    const stack = [[x, y]];
    const dirs = [[2, 0], [-2, 0], [0, 2], [0, -2]];
    while (stack.length) {
      const [cx, cy] = stack[stack.length - 1];
      const options = shuffle(dirs.slice());
      let advanced = false;
      for (const [dx, dy] of options) {
        const nx = cx + dx;
        const ny = cy + dy;
        if (nx > 0 && ny > 0 && nx < W - 1 && ny < H - 1 && g[ny][nx] === 1) {
          g[cy + dy / 2][cx + dx / 2] = 0;
          g[ny][nx] = 0;
          stack.push([nx, ny]);
          advanced = true;
          break;
        }
      }
      if (!advanced) stack.pop();
    }
    // Knock through some walls to create loops (less dead-end frustration).
    for (let i = 0; i < 46; i++) {
      const x = randInt(2, W - 3);
      const y = randInt(2, H - 3);
      if (g[y][x] === 1 && ((x % 2 === 0) !== (y % 2 === 0))) g[y][x] = 0;
    }
    // Wards / open rooms.
    for (let r = 0; r < 3; r++) {
      const cx = randInt(3, W - 4);
      const cy = randInt(3, H - 4);
      for (let yy = cy - 1; yy <= cy + 1; yy++) {
        for (let xx = cx - 1; xx <= cx + 1; xx++) {
          if (xx > 0 && yy > 0 && xx < W - 1 && yy < H - 1) g[yy][xx] = 0;
        }
      }
    }
    return g;
  }

  _layout() {
    const passages = [];
    for (let y = 1; y < H - 1; y++) {
      for (let x = 1; x < W - 1; x++) if (this.grid[y][x] === 0) passages.push([x, y]);
    }

    // Carve a long, clean opening corridor so the first sight of the demon is framed.
    const dirs = [[0, -1], [1, 0], [0, 1], [-1, 0]];
    let spot = null;
    for (const [sx, sy] of shuffle(passages.slice())) {
      for (const [dx, dy] of shuffle(dirs.slice())) {
        let okay = true;
        for (let i = 0; i < 10; i++) {
          const nx = sx + dx * i;
          const ny = sy + dy * i;
          if (nx < 1 || ny < 1 || nx >= W - 1 || ny >= H - 1) { okay = false; break; }
        }
        if (okay) { spot = { sx, sy, dx, dy }; break; }
      }
      if (spot) break;
    }
    if (!spot) spot = { sx: 1, sy: 1, dx: 1, dy: 0 };
    for (let i = 0; i < 10; i++) this.grid[spot.sy + spot.dy * i][spot.sx + spot.dx * i] = 0;

    const spawnCell = [spot.sx, spot.sy];
    const dist = this.distanceField(spawnCell);
    const spawnPos = this.cellCenter(spot.sx, spot.sy);

    // Demon waits two cells down the opening corridor.
    const demonCell = [spot.sx + spot.dx * 2, spot.sy + spot.dy * 2];
    const demonPos = this.cellCenter(demonCell[0], demonCell[1]);

    const yaw = Math.atan2(-spot.dx, -spot.dy);
    const spawn = { cell: spawnCell, pos: spawnPos, yaw, dir: [spot.dx, spot.dy], demonPos, demonCell };

    // Exit at the furthest reachable point.
    let exitCell = spawnCell;
    let best = -1;
    for (const [x, y] of this.openCells) {
      const d = dist[y * W + x];
      if (d > best) { best = d; exitCell = [x, y]; }
    }
    // Orient the exit gate toward the way back.
    let faceCell = [exitCell[0], exitCell[1] + 1];
    let bestFace = Infinity;
    for (const [dx, dy] of dirs) {
      const nx = exitCell[0] + dx;
      const ny = exitCell[1] + dy;
      if (this.isWall(nx, ny)) continue;
      const d = dist[ny * W + nx];
      if (d >= 0 && d < bestFace) { bestFace = d; faceCell = [nx, ny]; }
    }
    const exitPos = this.cellCenter(exitCell[0], exitCell[1]);

    // Spread five souls across the map.
    const chosen = [];
    const candidates = this.openCells.filter(([x, y]) => {
      const d = dist[y * W + x];
      return d >= 5 && !(Math.abs(x - spawnCell[0]) + Math.abs(y - spawnCell[1]) < 3);
    });
    const shuffled = shuffle(candidates.slice());
    for (const c of shuffled) {
      if (chosen.length >= CONFIG.soulsNeeded) break;
      if (chosen.some((o) => Math.abs(o[0] - c[0]) + Math.abs(o[1] - c[1]) < 6)) continue;
      if (Math.abs(c[0] - exitCell[0]) + Math.abs(c[1] - exitCell[1]) < 2) continue;
      chosen.push(c);
    }
    for (const c of shuffled) {
      if (chosen.length >= CONFIG.soulsNeeded) break;
      if (!chosen.some((o) => o[0] === c[0] && o[1] === c[1])) chosen.push(c);
    }
    const soulCells = chosen.slice(0, CONFIG.soulsNeeded);

    return {
      spawn, exitCell, exitPos, faceCell, demonCell, demonPos,
      soulCells, dist, spawnCell, openCells: this.openCells,
    };
  }

  _buildShell() {
    const { mats } = this.assets;
    const width = W * CELL;
    const depth = H * CELL;

    const floorGeo = new THREE.PlaneGeometry(width, depth);
    const floor = new THREE.Mesh(floorGeo, mats.floor);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.group.add(floor);

    const ceilGeo = new THREE.PlaneGeometry(width, depth);
    const ceiling = new THREE.Mesh(ceilGeo, mats.ceiling);
    ceiling.rotation.x = Math.PI / 2;
    ceiling.position.y = WALL_H;
    ceiling.receiveShadow = true;
    this.group.add(ceiling);

    const wallCells = [];
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (this.grid[y][x] !== 1) continue;
        let exposed = false;
        for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nx = x + dx;
          const ny = y + dy;
          if (nx >= 0 && ny >= 0 && nx < W && ny < H && this.grid[ny][nx] === 0) { exposed = true; break; }
        }
        if (exposed) wallCells.push([x, y]);
      }
    }

    const geo = new THREE.BoxGeometry(CELL, WALL_H, CELL);
    const mesh = new THREE.InstancedMesh(geo, mats.wall, wallCells.length);
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    wallCells.forEach(([x, y], i) => {
      dummy.position.set((x - (W - 1) / 2) * CELL, WALL_H / 2, (y - (H - 1) / 2) * CELL);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
      const v = rand(0.8, 1.03);
      color.setRGB(v, v, v * rand(0.94, 1.02));
      mesh.setColorAt(i, color);
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.castShadow = !IS_MOBILE_RENDER;
    mesh.receiveShadow = true;
    this.group.add(mesh);
  }

  _buildFixtures(layout) {
    const { mats } = this.assets;
    const choices = shuffle(this.openCells.filter(([x, y]) => {
      const d = layout.dist[y * W + x];
      return d > 4 && Math.abs(x - layout.spawnCell[0]) + Math.abs(y - layout.spawnCell[1]) > 4;
    })).slice(0, 7);

    choices.forEach(([x, y], i) => {
      const p = this.cellCenter(x, y);
      const mat = new THREE.MeshBasicMaterial({ color: 0xcfd6c4, toneMapped: false });
      const bar = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.07, 0.36), mat);
      bar.position.set(p.x, WALL_H - 0.12, p.z);
      this.group.add(bar);
      const cage = new THREE.Mesh(new THREE.BoxGeometry(1.66, 0.12, 0.5), mats.metalDark);
      cage.position.set(p.x, WALL_H - 0.17, p.z);
      this.group.add(cage);

      let light = null;
      if (i < 4) {
        light = new THREE.PointLight(0xc4d2bc, 9, 8.5, 1.8);
        light.position.set(p.x, WALL_H - 0.5, p.z);
        this.group.add(light);
      }
      this.fixtures.push({
        mat,
        light,
        base: light ? 9 : 0,
        phase: rand(0, 10),
        speed: rand(0.4, 1.6),
        flicker: i % 3 === 0,
        color: new THREE.Color(0xcfd6c4),
      });
    });
  }

  _buildProps(layout) {
    const rooms = this.openCells.filter(([x, y]) => {
      let open = 0;
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (!this.isWall(x + dx, y + dy)) open++;
      if (open < 3) return false;
      if (Math.abs(x - layout.spawnCell[0]) + Math.abs(y - layout.spawnCell[1]) < 4) return false;
      if (Math.abs(x - layout.exitCell[0]) + Math.abs(y - layout.exitCell[1]) < 2) return false;
      if (layout.soulCells.some(([sx, sy]) => sx === x && sy === y)) return false;
      return true;
    });

    const selected = shuffle(rooms.slice()).slice(0, 12);
    let count = 0;
    for (const [x, y] of selected) {
      if (Math.random() < 0.28) continue;
      const p = this.cellCenter(x, y);
      // Push furniture toward a nearby wall.
      let ox = 0;
      let oz = 0;
      const walls = [];
      if (this.isWall(x - 1, y)) walls.push([-1, 0]);
      if (this.isWall(x + 1, y)) walls.push([1, 0]);
      if (this.isWall(x, y - 1)) walls.push([0, -1]);
      if (this.isWall(x, y + 1)) walls.push([0, 1]);
      if (walls.length) {
        const [wx, wz] = pick(walls);
        ox = wx * (CELL / 2 - 1.0);
        oz = wz * (CELL / 2 - 1.0);
      }
      const px = p.x + ox;
      const pz = p.z + oz;
      const rot = Math.atan2(ox, oz) + (Math.random() < 0.5 ? Math.PI / 2 : 0);
      const type = count % 4;
      if (type === 0) this._bed(px, pz, rot, true);
      else if (type === 1) this._gurney(px, pz, rot);
      else if (type === 2) this._ivStand(px, pz);
      else this._cart(px, pz, rot);
      count++;
      if (count >= 9) break;
    }
  }

  _bed(x, z, rot, withCollider = true) {
    const { mats } = this.assets;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;

    const frame = new THREE.Mesh(new THREE.BoxGeometry(2.05, 0.1, 0.94), mats.metal);
    frame.position.y = 0.56;
    const mattress = new THREE.Mesh(new THREE.BoxGeometry(1.98, 0.19, 0.86), mats.mattress);
    mattress.position.y = 0.7;
    const sheet = new THREE.Mesh(new THREE.BoxGeometry(1.35, 0.035, 0.88), mats.sheet);
    sheet.position.set(0.26, 0.81, 0);
    sheet.rotation.z = 0.004;
    const pillow = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.1, 0.64), mats.sheet);
    pillow.position.set(-0.72, 0.83, 0);
    pillow.rotation.y = rand(-0.12, 0.12);
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.9, 0.98), mats.metalDark);
    head.position.set(-1.03, 0.78, 0);
    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.5, 0.96), mats.metalDark);
    foot.position.set(1.03, 0.56, 0);
    g.add(frame, mattress, sheet, pillow, head, foot);
    for (const sx of [-0.86, 0.86]) {
      for (const sz of [-0.36, 0.36]) {
        const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.032, 0.032, 0.55, 6), mats.metal);
        leg.position.set(sx, 0.28, sz);
        g.add(leg);
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.04, 8), mats.metalDark);
        wheel.rotation.x = Math.PI / 2;
        wheel.position.set(sx, 0.06, sz);
        g.add(wheel);
      }
    }
    g.traverse((o) => { if (o.isMesh) { o.castShadow = !IS_MOBILE_RENDER; o.receiveShadow = true; } });
    this.group.add(g);
    if (withCollider) this.colliders.push({ x, z, r: 0.72 });
  }

  _gurney(x, z, rot) {
    const { mats } = this.assets;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    const top = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.09, 0.7), mats.metal);
    top.position.y = 0.8;
    const pad = new THREE.Mesh(new THREE.BoxGeometry(1.7, 0.12, 0.64), mats.mattress);
    pad.position.y = 0.9;
    g.add(top, pad);
    for (const sx of [-0.72, 0.72]) {
      for (const sz of [-0.26, 0.26]) {
        const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, 0.78, 6), mats.metal);
        leg.position.set(sx, 0.4, sz);
        g.add(leg);
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.045, 8), mats.metalDark);
        wheel.rotation.x = Math.PI / 2;
        wheel.position.set(sx, 0.07, sz);
        g.add(wheel);
      }
    }
    g.traverse((o) => { if (o.isMesh) { o.castShadow = !IS_MOBILE_RENDER; o.receiveShadow = true; } });
    this.group.add(g);
    this.colliders.push({ x, z, r: 0.58 });
  }

  _ivStand(x, z) {
    const { mats } = this.assets;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.05, 10), mats.metalDark);
    base.position.y = 0.03;
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 1.85, 6), mats.metal);
    pole.position.y = 0.95;
    const bag = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.3, 0.05), new THREE.MeshStandardMaterial({ color: 0xa8b49a, roughness: 0.45, transparent: true, opacity: 0.75 }));
    bag.position.set(0.12, 1.55, 0);
    g.add(base, pole, bag);
    g.traverse((o) => { if (o.isMesh) o.castShadow = !IS_MOBILE_RENDER; });
    this.group.add(g);
    this.colliders.push({ x, z, r: 0.3 });
  }

  _cart(x, z, rot) {
    const { mats } = this.assets;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    for (let i = 0; i < 3; i++) {
      const shelf = new THREE.Mesh(new THREE.BoxGeometry(0.72, 0.035, 0.5), mats.metal);
      shelf.position.y = 0.3 + i * 0.38;
      g.add(shelf);
    }
    for (const sx of [-0.32, 0.32]) {
      for (const sz of [-0.21, 0.21]) {
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 1.08, 6), mats.metal);
        post.position.set(sx, 0.54, sz);
        g.add(post);
      }
    }
    g.traverse((o) => { if (o.isMesh) { o.castShadow = !IS_MOBILE_RENDER; o.receiveShadow = true; } });
    this.group.add(g);
    this.colliders.push({ x, z, r: 0.36 });
  }

  _buildSigns() {
    const wallFaces = [];
    for (const [x, y] of this.openCells) {
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        if (this.isWall(x + dx, y + dy)) wallFaces.push({ open: [x, y], dir: [dx, dy] });
      }
    }
    const chosen = shuffle(wallFaces).slice(0, 11);
    chosen.forEach((face, i) => {
      if (Math.random() < 0.2) return;
      const [word, color] = SIGN_WORDS[i % SIGN_WORDS.length];
      const mat = makeSign(word, color, '#08100b');
      const [ox, oy] = face.open;
      const [dx, dy] = face.dir;
      const p = this.cellCenter(ox, oy);
      const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.35, 0.34), mat);
      sign.position.set(p.x - dx * (CELL / 2 - 0.015), 2.32, p.z - dy * (CELL / 2 - 0.015));
      sign.rotation.y = Math.atan2(-dx, -dy);
      this.group.add(sign);
    });
  }

  _buildDecals() {
    const { mats } = this.assets;
    // Wall splatters
    const faces = [];
    for (const [x, y] of this.openCells) {
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        if (this.isWall(x + dx, y + dy)) faces.push({ open: [x, y], dir: [dx, dy] });
      }
    }
    shuffle(faces).slice(0, 12).forEach((face) => {
      const [ox, oy] = face.open;
      const [dx, dy] = face.dir;
      const p = this.cellCenter(ox, oy);
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(rand(1.1, 2.2), rand(1.2, 2.4)), mats.blood);
      mesh.position.set(p.x - dx * (CELL / 2 - 0.02), rand(0.8, 1.7), p.z - dy * (CELL / 2 - 0.02));
      mesh.rotation.y = Math.atan2(-dx, -dy);
      mesh.rotation.z = rand(0, Math.PI);
      this.group.add(mesh);
    });
    // Floor pools
    for (let i = 0; i < 18; i++) {
      const cell = pick(this.openCells);
      const p = this.cellCenter(cell[0], cell[1]);
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(rand(0.7, 2.1), rand(0.7, 2.1)), mats.blood);
      mesh.position.set(p.x + rand(-1.4, 1.4), 0.012, p.z + rand(-1.4, 1.4));
      mesh.rotation.x = -Math.PI / 2;
      mesh.rotation.z = rand(0, Math.PI * 2);
      this.group.add(mesh);
    }
  }

  _buildExit(layout) {
    const { mats } = this.assets;
    const p = layout.exitPos;
    const g = new THREE.Group();
    g.position.copy(p);
    const [fx, fy] = layout.faceCell;
    const dx = fx - layout.exitCell[0];
    const dz = fy - layout.exitCell[1];
    g.rotation.y = Math.atan2(dx, dz);

    const frame = new THREE.Mesh(new THREE.BoxGeometry(1.9, 2.72, 0.24), mats.metalDark);
    frame.position.y = 1.36;
    frame.position.z = -0.06;
    g.add(frame);

    const red = mats.exitRed;
    const panels = [];
    for (const side of [-1, 1]) {
      const panel = new THREE.Mesh(new THREE.BoxGeometry(0.78, 2.4, 0.1), red);
      panel.position.set(side * 0.42, 1.25, 0.1);
      panel.castShadow = !IS_MOBILE_RENDER;
      g.add(panel);
      panels.push(panel);
      const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 0.34, 6), mats.metal);
      handle.rotation.z = Math.PI / 2;
      handle.position.set(side * 0.11, 1.05, 0.18);
      g.add(handle);
    }

    const redSign = makeSign('EXIT', '#ff7060', '#160303');
    const greenSign = makeSign('EXIT', '#8dffb0', '#03140a');
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.05, 0.26), redSign);
    sign.position.set(0, 2.5, 0.14);
    g.add(sign);

    const halo = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.assets.glow, color: 0xff4a3a, transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.3,
    }));
    halo.position.set(0, 1.4, 0.12);
    halo.scale.set(3.6, 3.2, 1);
    g.add(halo);

    const light = new THREE.PointLight(0xff3a2a, 16, 8, 1.9);
    light.position.set(0, 2.15, 0.7);
    g.add(light);

    this.group.add(g);
    this.exit = { group: g, panels, sign, redSign, greenSign, halo, light, pos: p };
  }

  activateExit() {
    if (this.exitActive || !this.exit) return;
    this.exitActive = true;
    for (const panel of this.exit.panels) panel.material = this.assets.mats.exitGreen;
    this.exit.sign.material = this.exit.greenSign;
    this.exit.halo.material.color.setHex(0x5aff96);
    this.exit.halo.material.opacity = 0.45;
    this.exit.light.color.setHex(0x3aff7a);
    this.exit.light.intensity = 24;
  }

  _buildSouls(layout) {
    const soulMat = new THREE.MeshBasicMaterial({ color: 0xffd45a, toneMapped: false });
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffc23a, transparent: true, opacity: 0.55,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    });
    layout.soulCells.forEach(([x, y]) => {
      const p = this.cellCenter(x, y);
      p.y = 1.18;
      const g = new THREE.Group();
      g.position.copy(p);

      const core = new THREE.Mesh(new THREE.SphereGeometry(0.13, 18, 14), soulMat);
      g.add(core);
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.assets.glow, color: 0xffc83a, transparent: true,
        blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.95,
      }));
      halo.scale.set(1.55, 1.55, 1);
      g.add(halo);
      const beam = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.assets.glow, color: 0xffb52a, transparent: true,
        blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.11,
      }));
      beam.scale.set(1.15, 3.6, 1);
      g.add(beam);

      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.012, 6, 32), ringMat);
      ring.rotation.x = Math.PI / 2.5;
      g.add(ring);
      const ring2 = new THREE.Mesh(new THREE.TorusGeometry(0.36, 0.008, 6, 32), ringMat);
      ring2.rotation.x = Math.PI / 2;
      ring2.rotation.y = Math.PI / 3;
      g.add(ring2);

      this.group.add(g);
      this.souls.push({ group: g, core, halo, ring, ring2, pos: p.clone(), collected: false, phase: rand(0, 10) });
    });
  }

  _buildDust() {
    const count = IS_MOBILE_RENDER ? 240 : 460;
    const positions = new Float32Array(count * 3);
    const base = new Float32Array(count * 3);
    const phase = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      const [gx, gy] = pick(this.openCells);
      const p = this.cellCenter(gx, gy);
      const x = p.x + rand(-CELL / 2, CELL / 2);
      const z = p.z + rand(-CELL / 2, CELL / 2);
      const y = rand(0.2, WALL_H - 0.2);
      positions[i * 3] = base[i * 3] = x;
      positions[i * 3 + 1] = base[i * 3 + 1] = y;
      positions[i * 3 + 2] = base[i * 3 + 2] = z;
      phase[i] = rand(0, Math.PI * 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      map: this.assets.glow, color: 0x9fa79a, size: 0.075, sizeAttenuation: true,
      transparent: true, opacity: 0.32, depthWrite: false,
      blending: THREE.AdditiveBlending, toneMapped: false,
    });
    const points = new THREE.Points(geo, mat);
    points.frustumCulled = false;
    this.group.add(points);
    this.dust = { points, base, phase, count };
  }

  tryCollectSoul(pos) {
    for (const soul of this.souls) {
      if (soul.collected) continue;
      const dx = soul.pos.x - pos.x;
      const dz = soul.pos.z - pos.z;
      if (dx * dx + dz * dz < 1.45 * 1.45) {
        soul.collected = true;
        soul.group.visible = false;
        return soul;
      }
    }
    return null;
  }

  nearestSoulDistance(pos) {
    let best = Infinity;
    for (const soul of this.souls) {
      if (soul.collected) continue;
      best = Math.min(best, Math.hypot(soul.pos.x - pos.x, soul.pos.z - pos.z));
    }
    return best;
  }

  update(dt, time) {
    if (this.fixtures) {
      for (const f of this.fixtures) {
        let flick = 1;
        if (f.flicker) {
          const n = Math.sin(time * 11 + f.phase) * Math.sin(time * 3.7 + f.phase * 2);
          flick = n > 0.55 ? 0.18 : (Math.random() < 0.006 ? 0.1 : 1);
        }
        const pulse = 0.86 + Math.sin(time * f.speed + f.phase) * 0.14;
        if (f.light) f.light.intensity = f.base * pulse * flick;
        f.mat.color.copy(f.color).multiplyScalar(clamp01(pulse * flick));
      }
    }
    for (const soul of this.souls) {
      if (soul.collected) continue;
      const t = time + soul.phase;
      soul.group.position.y = 1.18 + Math.sin(t * 1.35) * 0.09;
      soul.ring.rotation.z += dt * 0.9;
      soul.ring2.rotation.z -= dt * 0.6;
      soul.halo.material.opacity = 0.78 + Math.sin(t * 2.1) * 0.16;
      const s = 1.5 + Math.sin(t * 2.1) * 0.12;
      soul.halo.scale.set(s, s, 1);
    }
    if (this.exit) {
      const t = time;
      this.exit.halo.material.opacity = (this.exitActive ? 0.42 : 0.26) + Math.sin(t * 2.3) * 0.08;
      this.exit.light.intensity = (this.exitActive ? 24 : 16) * (0.87 + Math.sin(t * 2.7) * 0.13);
    }
    if (this.dust) {
      const arr = this.dust.points.geometry.attributes.position.array;
      for (let i = 0; i < this.dust.count; i++) {
        arr[i * 3] = this.dust.base[i * 3] + Math.sin(time * 0.22 + this.dust.phase[i]) * 0.22;
        arr[i * 3 + 1] = this.dust.base[i * 3 + 1] + Math.sin(time * 0.35 + this.dust.phase[i] * 1.7) * 0.28;
        arr[i * 3 + 2] = this.dust.base[i * 3 + 2] + Math.cos(time * 0.19 + this.dust.phase[i]) * 0.22;
      }
      this.dust.points.geometry.attributes.position.needsUpdate = true;
    }
  }
}

const IS_MOBILE_RENDER = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
const clamp01 = (v) => Math.max(0, Math.min(1, v));

import * as THREE from '../vendor/three.module.js';
import { CONFIG, clamp, lerp, rand, pick } from './config.js';

const CELL = CONFIG.cell;

/* The thing that sees souls. */
export class SoulDemon {
  constructor(scene, assets) {
    this.scene = scene;
    this.assets = assets;
    this.group = new THREE.Group();
    this.group.visible = false;
    scene.add(this.group);
    this.state = 'dormant';
    this.path = null;
    this.pathIndex = 0;
    this.pathTimer = 0;
    this.lastSeen = 0;
    this.lastKnown = null;
    this.searchTimer = 0;
    this.growlTimer = 0;
    this.threat = 0;
    this.animTime = 0;
    this.caught = false;
    this._build();
  }

  _build() {
    const { mats, glow } = this.assets;

    const robePts = [];
    const profile = [
      [0.94, 0.02], [0.88, 0.32], [0.7, 0.72], [0.57, 1.12],
      [0.52, 1.42], [0.6, 1.62], [0.46, 1.78], [0.34, 1.84],
    ];
    for (const [x, y] of profile) robePts.push(new THREE.Vector2(x, y));
    const robeGeo = new THREE.LatheGeometry(robePts, 22);
    const pos = robeGeo.attributes.position;
    const v = new THREE.Vector3();
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i);
      if (v.y < 0.42) {
        const a = Math.atan2(v.z, v.x);
        const ragged = 1 + Math.sin(a * 9 + 0.7) * 0.07 + Math.sin(a * 23) * 0.02;
        v.x *= ragged;
        v.z *= ragged;
        if (v.y < 0.08) v.y = Math.abs(Math.sin(a * 7)) * 0.1;
      }
      pos.setXYZ(i, v.x, v.y, v.z);
    }
    robeGeo.computeVertexNormals();
    const robe = new THREE.Mesh(robeGeo, mats.robe);
    robe.castShadow = true;
    this.group.add(robe);

    const chest = new THREE.Mesh(new THREE.SphereGeometry(0.52, 20, 16), mats.robe);
    chest.scale.set(1.05, 0.72, 0.62);
    chest.position.y = 1.56;
    chest.castShadow = true;
    this.group.add(chest);

    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.12, 0.52, 9), mats.skin);
    neck.position.set(0, 1.97, 0.02);
    neck.castShadow = true;
    this.group.add(neck);

    const head = new THREE.Group();
    head.position.set(0, 2.22, 0.03);
    this.head = head;
    this.group.add(head);

    const skull = new THREE.Mesh(new THREE.SphereGeometry(0.37, 28, 22), mats.skin);
    skull.scale.set(1, 1.12, 1.06);
    skull.position.y = 0.01;
    skull.castShadow = true;
    head.add(skull);

    const face = new THREE.Mesh(new THREE.SphereGeometry(0.28, 24, 18), mats.skin);
    face.scale.set(1.0, 0.84, 0.78);
    face.position.set(0, -0.16, 0.11);
    face.castShadow = true;
    head.add(face);

    const jaw = new THREE.Group();
    jaw.position.set(0, -0.34, 0.07);
    head.add(jaw);
    const jawMesh = new THREE.Mesh(new THREE.SphereGeometry(0.24, 20, 14), mats.skin);
    jawMesh.scale.set(1.04, 0.5, 0.92);
    jawMesh.position.y = -0.01;
    jawMesh.castShadow = true;
    jaw.add(jawMesh);

    const mouth = new THREE.Mesh(new THREE.SphereGeometry(0.19, 16, 12), mats.black);
    mouth.scale.set(1.15, 0.62, 0.55);
    mouth.position.set(0, -0.2, 0.24);
    head.add(mouth);

    // upper teeth
    for (let i = 0; i < 7; i++) {
      const x = (i - 3) * 0.047;
      const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.03, rand(0.1, 0.15), 5), mats.bone);
      tooth.position.set(x, -0.235 - Math.abs(i - 3) * 0.005, 0.335);
      tooth.rotation.x = Math.PI;
      tooth.rotation.z = rand(-0.14, 0.14);
      tooth.castShadow = true;
      head.add(tooth);
    }
    // lower teeth
    for (let i = 0; i < 6; i++) {
      const x = (i - 2.5) * 0.052;
      const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.028, rand(0.08, 0.13), 5), mats.bone);
      tooth.position.set(x, -0.44 + Math.abs(i - 2.5) * 0.004, 0.315);
      tooth.rotation.z = rand(-0.14, 0.14);
      tooth.castShadow = true;
      jaw.add(tooth);
    }

    // eye sockets & burning eyes
    this.eyeGlows = [];
    this.eyeMats = [];
    for (const side of [-1, 1]) {
      const socket = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 12), mats.black);
      socket.scale.set(1.2, 1.05, 0.72);
      socket.position.set(side * 0.155, 0.055, 0.285);
      head.add(socket);

      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.077, 16, 12), mats.eye.clone());
      eye.position.set(side * 0.155, 0.06, 0.345);
      head.add(eye);
      this.eyeMats.push(eye.material);

      const glowSprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glow, color: 0xffc32e, transparent: true,
        blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.9,
      }));
      glowSprite.position.set(side * 0.155, 0.06, 0.4);
      glowSprite.scale.set(0.62, 0.62, 1);
      head.add(glowSprite);
      this.eyeGlows.push(glowSprite);

      const brow = new THREE.Mesh(new THREE.BoxGeometry(0.21, 0.052, 0.13), mats.skin);
      brow.position.set(side * 0.16, 0.175, 0.29);
      brow.rotation.z = side * 0.2;
      brow.rotation.x = -0.1;
      head.add(brow);

      const cheek = new THREE.Mesh(new THREE.SphereGeometry(0.1, 12, 10), mats.skin);
      cheek.scale.set(1.15, 0.55, 0.9);
      cheek.position.set(side * 0.24, -0.12, 0.2);
      head.add(cheek);
    }

    for (const side of [-1, 1]) {
      const nostril = new THREE.Mesh(new THREE.SphereGeometry(0.028, 8, 6), mats.black);
      nostril.position.set(side * 0.042, -0.13, 0.345);
      head.add(nostril);
    }

    // Fibrous strands hanging around the skull.
    const strandMat = new THREE.MeshStandardMaterial({ color: 0x8e8574, roughness: 0.95 });
    const up = new THREE.Vector3(0, 1, 0);
    for (let i = 0; i < 26; i++) {
      const a = rand(0, Math.PI * 2);
      const upness = rand(-0.15, 0.9);
      const dir = new THREE.Vector3(Math.cos(a), upness, Math.sin(a)).normalize();
      const len = rand(0.28, 0.95);
      const strand = new THREE.Mesh(new THREE.ConeGeometry(rand(0.004, 0.011), len, 4), strandMat);
      const base = new THREE.Vector3(dir.x * 0.26, 0.22 + dir.y * 0.24, dir.z * 0.26);
      strand.position.copy(base).addScaledVector(dir, len * 0.45);
      strand.quaternion.setFromUnitVectors(up, dir);
      strand.rotation.z += rand(-0.25, 0.25);
      head.add(strand);
    }

    // Arms
    this.arms = [];
    for (const side of [-1, 1]) {
      const arm = new THREE.Group();
      arm.position.set(side * 0.5, 1.62, 0.02);
      arm.rotation.z = side * 0.26;
      arm.rotation.x = -0.12;
      const upper = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.075, 0.82, 7), mats.skin);
      upper.position.y = -0.41;
      upper.castShadow = true;
      const fore = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.058, 0.66, 7), mats.skin);
      fore.position.y = -1.02;
      fore.castShadow = true;
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.09, 10, 8), mats.skin);
      hand.scale.set(0.8, 1.15, 0.7);
      hand.position.y = -1.37;
      arm.add(upper, fore, hand);
      for (let c = 0; c < 4; c++) {
        const claw = new THREE.Mesh(new THREE.ConeGeometry(0.017, rand(0.14, 0.22), 5), mats.bone);
        claw.position.set((c - 1.5) * 0.045, -1.48, 0.03);
        claw.rotation.x = Math.PI + rand(-0.16, 0.16);
        claw.rotation.z = rand(-0.2, 0.2);
        arm.add(claw);
      }
      this.group.add(arm);
      this.arms.push(arm);
    }

    // Eye light bleeds into the corridor.
    this.eyeLight = new THREE.PointLight(0xffb020, 5.5, 6.5, 1.9);
    this.eyeLight.position.set(0, 2.25, 0.2);
    this.group.add(this.eyeLight);

    const aura = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glow, color: 0xffa818, transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.12,
    }));
    aura.scale.set(3.2, 3.6, 1);
    aura.position.y = 2.05;
    this.group.add(aura);
    this.aura = aura;

    this.group.traverse((o) => { if (o.isMesh) o.frustumCulled = false; });
  }

  spawn(pos, playerPos) {
    this.group.visible = true;
    this.group.position.set(pos.x, 0, pos.z);
    this.group.rotation.set(0, Math.atan2(playerPos.x - pos.x, playerPos.z - pos.z), 0);
    this.state = 'dormant';
    this.path = null;
    this.pathIndex = 0;
    this.pathTimer = 0;
    this.lastSeen = 0;
    this.lastKnown = null;
    this.searchTimer = 0;
    this.growlTimer = 0;
    this.threat = 0;
    this.caught = false;
    this.animTime = 0;
    this.head.rotation.set(0, 0, 0);
    this.jaw = this.jaw;
  }

  placeForScare(playerPos, yaw) {
    const fx = -Math.sin(yaw);
    const fz = -Math.cos(yaw);
    const px = playerPos.x + fx * 2.05;
    const pz = playerPos.z + fz * 2.05;
    this.group.visible = true;
    this.group.position.set(px, 0, pz);
    this.group.rotation.set(0, Math.atan2(playerPos.x - px, playerPos.z - pz), 0);
    this.head.rotation.set(-0.1, 0, 0);
    this.state = 'scare';
  }

  update(dt, time, ctx) {
    this.animTime += dt;
    const p = this.group.position;
    const player = ctx.playerPos;
    const dx = player.x - p.x;
    const dz = player.z - p.z;
    const dist = Math.hypot(dx, dz);

    const active = ctx.mode === 'playing' && ctx.grace <= 0;
    const headPos = new THREE.Vector3(p.x, 2.25, p.z);
    const eyePos = new THREE.Vector3(player.x, CONFIG.eyeHeight, player.z);
    const clear = ctx.world.lineOfSight(headPos, eyePos);
    const seeRange = ctx.flashlightOn ? 24 : 14.5;
    const sees = active && clear && dist < seeRange;
    const hears = active && ctx.sprinting && dist < 16;
    const close = active && clear && dist < 3.3;

    if (ctx.mode === 'playing') {
      if (sees || hears || close) {
        if (this.state !== 'hunt' && this.state !== 'scare') {
          this.state = 'hunt';
          this.growlTimer = 0;
          if (ctx.onGrowl) ctx.onGrowl(false);
        }
        this.state = this.state === 'scare' ? 'scare' : 'hunt';
        this.lastSeen = 0;
        this.lastKnown = ctx.world.cellOf(player.x, player.z);
      } else if (this.state === 'hunt') {
        this.lastSeen += dt;
        if (this.lastSeen > 4.2) {
          this.state = 'search';
          this.searchTimer = 8;
          this.path = null;
        }
      } else if (this.state === 'dormant' && active) {
        this.state = 'stalk';
      } else if (this.state === 'search') {
        this.searchTimer -= dt;
        if (this.searchTimer <= 0) {
          this.state = 'stalk';
          this.path = null;
        }
      }
    }

    if (this.state === 'scare') {
      const bob = Math.sin(this.animTime * 20) * 0.015;
      this.group.position.y = bob;
      this.head.rotation.z = Math.sin(this.animTime * 30) * 0.05;
      this._animateEyes(time, 1);
      return dist;
    }

    let target = null;
    let speed = 0;
    if (this.state === 'hunt') {
      speed = 3.92;
      if (clear && dist < 9) {
        target = { x: player.x, z: player.z };
      } else {
        this._repath(ctx.world, player, dt, 0.32);
        target = this._waypoint(ctx.world, dt);
      }
      this.growlTimer -= dt;
      if (this.growlTimer <= 0) {
        this.growlTimer = rand(1.8, 3.4);
        if (ctx.onGrowl) ctx.onGrowl(true);
      }
    } else if (this.state === 'search') {
      speed = 2.15;
      if (this.searchTimer === 8 || !this.lastKnown) {
        this.lastKnown = ctx.world.cellOf(player.x, player.z);
      }
      this._repath(ctx.world, { x: this._lastKnownPos(ctx.world).x, z: this._lastKnownPos(ctx.world).z }, dt, 0.5);
      target = this._waypoint(ctx.world, dt);
    } else if (this.state === 'stalk') {
      speed = dist < 7 ? 2.05 : 1.62;
      this._repath(ctx.world, player, dt, 0.55);
      target = this._waypoint(ctx.world, dt);
    } else if (this.state === 'dormant') {
      // The first stare. Face the player, barely moving.
      this.group.rotation.y = Math.atan2(dx, dz);
    }

    if (target) {
      const tx = target.x - p.x;
      const tz = target.z - p.z;
      const td = Math.hypot(tx, tz);
      if (td > 0.02) {
        const wantYaw = Math.atan2(tx, tz);
        this.group.rotation.y = lerpAngle(this.group.rotation.y, wantYaw, 1 - Math.exp(-dt * 7));
        const step = Math.min(speed * dt, td);
        const nx = p.x + (tx / td) * step;
        const nz = p.z + (tz / td) * step;
        if (ctx.world.canStand(nx, nz, 0.52, true)) {
          p.x = nx;
          p.z = nz;
        } else {
          if (ctx.world.canStand(nx, p.z, 0.52, true)) p.x = nx;
          if (ctx.world.canStand(p.x, nz, 0.52, true)) p.z = nz;
          this.path = null;
        }
      }
    }

    // Body language
    const hunting = this.state === 'hunt';
    const breathe = Math.sin(this.animTime * (hunting ? 6 : 1.4)) * (hunting ? 0.035 : 0.022);
    p.y = breathe;
    this.head.rotation.z = Math.sin(this.animTime * 1.1) * 0.045;
    this.head.rotation.x = hunting ? 0.16 : Math.sin(this.animTime * 0.7) * 0.03;
    this.head.rotation.y = Math.sin(this.animTime * 0.5) * 0.06;
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const arm = this.arms[i];
      arm.rotation.x = (hunting ? -1.18 : -0.14) + Math.sin(this.animTime * (hunting ? 5 : 1.2) + i) * (hunting ? 0.12 : 0.05);
      arm.rotation.z = side * (hunting ? 0.42 : 0.26) + Math.sin(this.animTime * 1.5 + i) * 0.03;
    }
    const jawOpen = hunting ? 0.11 : Math.sin(this.animTime * 1.3) * 0.012;
    this.head.children.forEach((c) => {});
    this._animateEyes(time, hunting ? 1.25 : 1);

    const speedFactor = this.state === 'dormant' ? 0 : 1;
    this.threat = lerp(this.threat, hunting ? clamp(1 - dist / 19, 0.12, 1) : clamp(1 - dist / 15, 0, 0.42) * 0.5, 0.08);

    if (active && !this.caught && dist < 1.34) {
      this.caught = true;
      if (ctx.onCatch) ctx.onCatch();
    }
    return dist;
  }

  _animateEyes(time, intensity) {
    const pulse = 0.92 + Math.sin(time * 4.2) * 0.08 + Math.sin(time * 13.7) * 0.03;
    for (const s of this.eyeGlows) {
      s.material.opacity = 0.75 + pulse * 0.22;
      const scale = (0.55 + pulse * 0.14) * (0.9 + intensity * 0.12);
      s.scale.set(scale, scale, 1);
    }
    if (this.eyeLight) this.eyeLight.intensity = (4.2 + pulse * 2.6) * intensity;
    if (this.aura) this.aura.material.opacity = 0.07 + Math.sin(time * 2.2) * 0.03;
  }

  _lastKnownPos(world) {
    if (!this.lastKnown) return { x: this.group.position.x, z: this.group.position.z };
    return world.cellCenter(this.lastKnown[0], this.lastKnown[1]);
  }

  _repath(world, target, dt, interval) {
    this.pathTimer -= dt;
    if (this.pathTimer > 0 && this.path) return;
    this.pathTimer = interval;
    const start = world.cellOf(this.group.position.x, this.group.position.z);
    const goal = world.cellOf(target.x, target.z);
    if (start[0] === goal[0] && start[1] === goal[1]) { this.path = null; return; }
    this.path = world.bfs(start, goal);
    this.pathIndex = this.path && this.path.length > 1 ? 1 : 0;
  }

  _waypoint(world, dt) {
    if (!this.path || this.path.length === 0) {
      // No path: drift in place so it never freezes.
      return null;
    }
    while (this.pathIndex < this.path.length) {
      const c = this.path[this.pathIndex];
      const p = world.cellCenter(c[0], c[1]);
      const d = Math.hypot(p.x - this.group.position.x, p.z - this.group.position.z);
      if (d < 0.46) {
        this.pathIndex++;
        continue;
      }
      return p;
    }
    return null;
  }
}

function lerpAngle(a, b, t) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

function clamp01(v) { return clamp(v, 0, 1); }

import * as THREE from '../vendor/three.module.js';
import { CONFIG, IS_MOBILE, clamp, lerp, wrapAngle } from './config.js';
import { createAssets } from './textures.js';
import { HospitalWorld } from './world.js';
import { SoulDemon } from './demon.js';
import { AudioEngine } from './audio.js';

const $ = (id) => document.getElementById(id);

const canvas = $('scene');
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance',
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, IS_MOBILE ? 1.6 : 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.shadowMap.enabled = !IS_MOBILE;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x040505);
scene.fog = new THREE.FogExp2(0x040505, 0.058);

const camera = new THREE.PerspectiveCamera(71, window.innerWidth / window.innerHeight, 0.05, 130);
camera.rotation.order = 'YXZ';
scene.add(camera);

const assets = createAssets(renderer);
const world = new HospitalWorld(scene, assets);
const demon = new SoulDemon(scene, assets);
const audio = new AudioEngine();

/* ---------------- flashlight ---------------- */

const flashlight = new THREE.SpotLight(0xfff0cf, 105, 30, Math.PI * 0.165, 0.62, 1.35);
flashlight.position.set(0.17, -0.1, 0.02);
flashlight.target.position.set(0, -0.04, -1);
flashlight.castShadow = !IS_MOBILE;
if (!IS_MOBILE) {
  flashlight.shadow.mapSize.set(1024, 1024);
  flashlight.shadow.camera.near = 0.2;
  flashlight.shadow.camera.far = 30;
  flashlight.shadow.bias = -0.0012;
  flashlight.shadow.normalBias = 0.025;
}
camera.add(flashlight);
camera.add(flashlight.target);

const hemi = new THREE.HemisphereLight(0x3c4148, 0x08090a, 0.42);
scene.add(hemi);
const ambient = new THREE.AmbientLight(0x232622, 0.16);
scene.add(ambient);

/* ---------------- state ---------------- */

const state = {
  mode: 'menu',
  pos: new THREE.Vector3(),
  yaw: 1.2,
  pitch: 0,
  stamina: 100,
  elapsed: 0,
  visualTime: 0,
  grace: CONFIG.grace,
  collected: 0,
  flashlightOn: true,
  muted: false,
  speed: 0,
  bob: 0,
  stepTimer: 0,
  threat: 0,
  deathT: 0,
  flashOpacity: 0,
  shake: 0,
  hintUntil: 0,
  hintText: '',
  exitSealedAt: -10,
  pointerLocked: false,
  dragging: false,
  dragId: null,
  dragX: 0,
  dragY: 0,
  joyId: null,
  joyX: 0,
  joyY: 0,
  touchSprint: false,
  sprintHeld: false,
  lastClock: '',
  wins: 0,
};

let layout = null;
let clock = 0;
let last = performance.now();

/* ---------------- UI helpers ---------------- */

const ui = {
  start: $('startScreen'),
  pause: $('pauseScreen'),
  dead: $('deadScreen'),
  win: $('winScreen'),
  hint: $('hint'),
  clock: $('clock'),
  pips: [...document.querySelectorAll('#soulPips i')],
  stamina: $('stamina'),
  threat: $('threat'),
  flash: $('flash'),
  compass: $('compass'),
  compassArrow: document.querySelector('#compass .arrow'),
  compassDist: document.querySelector('#compass .dist'),
  boot: $('boot'),
};

function hideScreens() {
  for (const el of [ui.start, ui.pause, ui.dead, ui.win]) el.classList.add('hidden');
}

function showHint(text, danger = false, ms = 3200) {
  ui.hint.textContent = text;
  ui.hint.classList.toggle('danger', danger);
  ui.hint.classList.add('show');
  state.hintUntil = performance.now() + ms;
}

function clearHint() {
  ui.hint.classList.remove('show');
  state.hintUntil = 0;
}

function updatePips() {
  ui.pips.forEach((pip, i) => pip.classList.toggle('on', i < state.collected));
}

function formatTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

function setFlash(opacity, color = null) {
  state.flashOpacity = opacity;
  if (color) ui.flash.style.background = color;
  ui.flash.style.opacity = String(opacity);
}

function setSoundLabels() {
  const label = `Sound: ${state.muted ? 'off' : 'on'}`;
  const btn = $('pauseSoundBtn');
  if (btn) btn.textContent = label;
  const hud = $('muteBtn');
  if (hud) {
    hud.textContent = state.muted ? 'MUTE' : 'SND';
    hud.classList.toggle('active', state.muted);
  }
}

function toggleMute() {
  state.muted = !state.muted;
  audio.setMuted(state.muted);
  setSoundLabels();
}

/* ---------------- run lifecycle ---------------- */

function placePlayer(l) {
  state.pos.copy(l.spawn.pos);
  state.yaw = l.spawn.yaw;
  state.pitch = 0;
  state.speed = 0;
  state.bob = 0;
  state.stamina = 100;
  state.stepTimer = 0;
  camera.position.set(state.pos.x, CONFIG.eyeHeight, state.pos.z);
  camera.rotation.set(0, state.yaw, 0);
}

function prepareRun(l) {
  layout = l;
  placePlayer(l);
  demon.spawn(l.demonPos, l.spawn.pos);
  state.collected = 0;
  state.elapsed = 0;
  state.grace = CONFIG.grace;
  state.threat = 0;
  state.flashOpacity = 0;
  state.shake = 0;
  state.exitSealedAt = -10;
  state.lastClock = '';
  ui.flash.style.opacity = '0';
  ui.threat.style.opacity = '0';
  ui.compass.classList.remove('show');
  updatePips();
  ui.clock.textContent = '00:00';
  ui.stamina.style.width = '100%';
  flashlight.visible = true;
  state.flashlightOn = true;
  $('lightBtn').classList.add('active');
}

function startRun(fresh = false) {
  audio.init();
  hideScreens();
  if (fresh) {
    prepareRun(world.generate());
  } else {
    prepareRun(layout || world.generate());
  }
  state.mode = 'playing';
  last = performance.now();
  showHint('Find the five souls. Stay out of its sight.', false, 4200);
  if (!IS_MOBILE && document.pointerLockElement !== canvas) {
    try {
      const p = canvas.requestPointerLock?.();
      if (p && p.catch) p.catch(() => {});
    } catch { /* drag look still works */ }
  }
}

function restartRun() {
  audio.init();
  hideScreens();
  prepareRun(world.generate());
  state.mode = 'playing';
  last = performance.now();
  showHint('Find the five souls. Stay out of its sight.', false, 4200);
}

function pauseGame() {
  if (state.mode !== 'playing') return;
  state.mode = 'paused';
  ui.pause.classList.remove('hidden');
  clearHint();
  if (document.pointerLockElement === canvas) document.exitPointerLock?.();
}

function resumeGame() {
  if (state.mode !== 'paused') return;
  ui.pause.classList.add('hidden');
  state.mode = 'playing';
  state.lastClock = '';
  last = performance.now();
  audio.init();
}

function beginDeath() {
  if (state.mode !== 'playing') return;
  state.mode = 'dying';
  state.deathT = 0;
  state.shake = 1;
  clearHint();
  audio.scare();
  demon.placeForScare(state.pos, state.yaw);
  const overlay = 'radial-gradient(circle at 50% 46%, rgba(255,240,195,.95), rgba(190,20,12,.6) 42%, rgba(20,0,0,.96))';
  setFlash(1, overlay);
}

function finishDeath() {
  if (state.mode === 'dead') return;
  state.mode = 'dead';
  setFlash(0, null);
  ui.threat.style.opacity = '0';
  $('deadSub').textContent = `${state.collected} of ${CONFIG.soulsNeeded} souls claimed. Your dark waits for you.`;
  ui.dead.classList.remove('hidden');
}

function winRun() {
  if (state.mode !== 'playing') return;
  state.mode = 'won';
  state.wins++;
  audio.exitChime();
  clearHint();
  $('winSub').textContent = `Escaped in ${formatTime(state.elapsed)} with five souls.`;
  ui.compass.classList.remove('show');
  setFlash(0.9, 'radial-gradient(circle at 50% 50%, rgba(255,246,210,.95), rgba(255,190,40,.45) 40%, rgba(0,0,0,.9))');
  setTimeout(() => setFlash(0), 700);
  setTimeout(() => {
    if (state.mode === 'won') ui.win.classList.remove('hidden');
  }, 650);
}

/* ---------------- input ---------------- */

const keys = { forward: false, back: false, left: false, right: false, sprint: false };

function moveInput() {
  let x = state.joyX;
  let y = state.joyY;
  if (keys.forward) y += 1;
  if (keys.back) y -= 1;
  if (keys.left) x -= 1;
  if (keys.right) x += 1;
  const len = Math.hypot(x, y);
  if (len > 1) { x /= len; y /= len; }
  return { x, y, moving: len > 0.08 };
}

window.addEventListener('keydown', (e) => {
  if (e.code === 'Escape') {
    if (state.mode === 'playing') { pauseGame(); e.preventDefault(); }
    else if (state.mode === 'paused') { resumeGame(); e.preventDefault(); }
    return;
  }
  if (state.mode === 'menu' && (e.code === 'Enter' || e.code === 'Space')) {
    startRun();
    e.preventDefault();
    return;
  }
  if (e.code === 'KeyF' && state.mode === 'playing') { toggleFlashlight(); return; }
  if (e.code === 'KeyM') { toggleMute(); return; }
  if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') { keys.sprint = true; state.sprintHeld = true; return; }
  if (e.code === 'KeyW' || e.code === 'ArrowUp') keys.forward = true;
  else if (e.code === 'KeyS' || e.code === 'ArrowDown') keys.back = true;
  else if (e.code === 'KeyA' || e.code === 'ArrowLeft') keys.left = true;
  else if (e.code === 'KeyD' || e.code === 'ArrowRight') keys.right = true;
});

window.addEventListener('keyup', (e) => {
  if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') { keys.sprint = false; state.sprintHeld = false; }
  if (e.code === 'KeyW' || e.code === 'ArrowUp') keys.forward = false;
  else if (e.code === 'KeyS' || e.code === 'ArrowDown') keys.back = false;
  else if (e.code === 'KeyA' || e.code === 'ArrowLeft') keys.left = false;
  else if (e.code === 'KeyD' || e.code === 'ArrowRight') keys.right = false;
});

window.addEventListener('blur', () => {
  keys.forward = keys.back = keys.left = keys.right = false;
  keys.sprint = false;
  state.touchSprint = false;
  state.joyX = state.joyY = 0;
});

document.addEventListener('pointerlockchange', () => {
  state.pointerLocked = document.pointerLockElement === canvas;
});
document.addEventListener('pointerlockerror', () => { state.pointerLocked = false; });

canvas.addEventListener('pointerdown', (e) => {
  if (state.mode !== 'playing') return;
  if (e.pointerType === 'mouse' && document.pointerLockElement !== canvas) {
    try {
      const p = canvas.requestPointerLock?.();
      if (p && p.catch) p.catch(() => {});
    } catch { /* ignore */ }
  }
  state.dragging = true;
  state.dragId = e.pointerId;
  state.dragX = e.clientX;
  state.dragY = e.clientY;
});

canvas.addEventListener('pointermove', (e) => {
  if (state.mode !== 'playing') return;
  let dx = 0;
  let dy = 0;
  if (document.pointerLockElement === canvas && e.pointerType === 'mouse') {
    dx = e.movementX || 0;
    dy = e.movementY || 0;
  } else {
    if (!state.dragging || e.pointerId !== state.dragId) return;
    dx = e.clientX - state.dragX;
    dy = e.clientY - state.dragY;
    state.dragX = e.clientX;
    state.dragY = e.clientY;
  }
  const sens = e.pointerType === 'touch' ? CONFIG.touchSensitivity : CONFIG.sensitivity;
  state.yaw -= dx * sens;
  state.pitch = clamp(state.pitch - dy * sens, -1.22, 1.15);
});

function endDrag(e) {
  if (state.dragId === null || (e && e.pointerId !== state.dragId)) return;
  state.dragging = false;
  state.dragId = null;
}
canvas.addEventListener('pointerup', endDrag);
canvas.addEventListener('pointercancel', endDrag);
canvas.addEventListener('contextmenu', (e) => e.preventDefault());

/* joystick */

const joystick = $('joystick');
const stick = $('stick');
let joyCenter = { x: 0, y: 0 };
const JOY_RADIUS = 40;

function joyMove(e) {
  const dx = e.clientX - joyCenter.x;
  const dy = e.clientY - joyCenter.y;
  const len = Math.hypot(dx, dy);
  const max = JOY_RADIUS;
  const k = len > max ? max / len : 1;
  const sx = dx * k;
  const sy = dy * k;
  stick.style.transform = `translate(${sx}px, ${sy}px)`;
  state.joyX = clamp(sx / max, -1, 1);
  state.joyY = clamp(-sy / max, -1, 1);
}

joystick.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  e.stopPropagation();
  state.joyId = e.pointerId;
  joystick.classList.add('active');
  joystick.setPointerCapture?.(e.pointerId);
  const rect = joystick.getBoundingClientRect();
  joyCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
  joyMove(e);
});
joystick.addEventListener('pointermove', (e) => {
  if (state.joyId !== e.pointerId) return;
  e.preventDefault();
  joyMove(e);
});
function joyEnd(e) {
  if (state.joyId !== e.pointerId) return;
  state.joyId = null;
  state.joyX = 0;
  state.joyY = 0;
  stick.style.transform = 'translate(0px, 0px)';
  joystick.classList.remove('active');
}
joystick.addEventListener('pointerup', joyEnd);
joystick.addEventListener('pointercancel', joyEnd);
joystick.addEventListener('lostpointercapture', joyEnd);

/* buttons */

function bindPress(el, down, up) {
  el.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    e.stopPropagation();
    el.classList.add('active');
    el.setPointerCapture?.(e.pointerId);
    down?.();
  });
  const finish = (e) => {
    if (e) e.preventDefault();
    el.classList.remove('active');
    up?.();
  };
  el.addEventListener('pointerup', finish);
  el.addEventListener('pointercancel', finish);
  el.addEventListener('pointerleave', (e) => { if (e.buttons === 0) finish(e); });
}

const sprintBtn = $('sprintBtn');
bindPress(sprintBtn, () => { state.touchSprint = true; }, () => { state.touchSprint = false; });

function toggleFlashlight() {
  if (state.mode !== 'playing') return;
  state.flashlightOn = !state.flashlightOn;
  flashlight.visible = state.flashlightOn;
  $('lightBtn').classList.toggle('active', state.flashlightOn);
  audio.whisper();
}

$('lightBtn').addEventListener('pointerdown', (e) => { e.preventDefault(); e.stopPropagation(); toggleFlashlight(); });
$('muteBtn').addEventListener('pointerdown', (e) => { e.preventDefault(); e.stopPropagation(); toggleMute(); });
$('pauseBtn').addEventListener('click', (e) => { e.stopPropagation(); pauseGame(); });
$('startBtn').addEventListener('click', (e) => { e.stopPropagation(); startRun(false); });
$('resumeBtn').addEventListener('click', resumeGame);
$('restartBtn').addEventListener('click', restartRun);
$('retryBtn').addEventListener('click', restartRun);
$('againBtn').addEventListener('click', restartRun);
$('pauseSoundBtn').addEventListener('click', toggleMute);

/* ---------------- gameplay update ---------------- */

function updatePlaying(dt) {
  state.visualTime += dt;
  state.elapsed += dt;
  state.grace = Math.max(0, state.grace - dt);

  const input = moveInput();
  const forward = new THREE.Vector3(-Math.sin(state.yaw), 0, -Math.cos(state.yaw));
  const right = new THREE.Vector3(Math.cos(state.yaw), 0, -Math.sin(state.yaw));
  const wish = new THREE.Vector3()
    .addScaledVector(forward, input.y)
    .addScaledVector(right, input.x);
  if (wish.lengthSq() > 0) wish.normalize();

  const wantsSprint = (keys.sprint || state.touchSprint) && input.moving;
  const canSprint = state.stamina > 0.5;
  const sprinting = wantsSprint && canSprint;
  if (sprinting) state.stamina = Math.max(0, state.stamina - 25 * dt);
  else state.stamina = Math.min(100, state.stamina + (input.moving ? 10 : 17) * dt);

  const targetSpeed = input.moving ? (sprinting ? CONFIG.sprintSpeed : CONFIG.walkSpeed) : 0;
  state.speed = lerp(state.speed, targetSpeed, 1 - Math.exp(-dt * 11));

  if (input.moving) {
    const stepX = wish.x * state.speed * dt;
    const stepZ = wish.z * state.speed * dt;
    const nx = state.pos.x + stepX;
    const nz = state.pos.z + stepZ;
    if (world.canStand(nx, state.pos.z)) state.pos.x = nx;
    if (world.canStand(state.pos.x, nz)) state.pos.z = nz;
  }

  // head bob and footsteps
  const moving = input.moving && state.speed > 0.4;
  state.bob += dt * state.speed * (sprinting ? 2.15 : 1.9);
  const bobAmt = sprinting ? 0.06 : 0.032;
  const bobY = moving ? Math.sin(state.bob * 2) * bobAmt : Math.sin(state.visualTime * 1.2) * 0.006;
  const bobRoll = moving ? Math.sin(state.bob) * (sprinting ? 0.008 : 0.004) : 0;

  camera.position.set(state.pos.x, CONFIG.eyeHeight + bobY, state.pos.z);
  camera.rotation.set(state.pitch, state.yaw, bobRoll);

  if (moving) {
    state.stepTimer -= dt;
    if (state.stepTimer <= 0) {
      audio.footstep(sprinting);
      state.stepTimer = sprinting ? 0.31 : 0.47;
    }
  } else {
    state.stepTimer = Math.min(state.stepTimer, 0.1);
  }

  // flashlight life
  const flickerSeed = Math.sin(state.visualTime * 17.3 + 1.7) * Math.sin(state.visualTime * 5.1);
  const flicker = flickerSeed > 0.982 ? 0.35 : (Math.sin(state.visualTime * 61) > 0.995 ? 0.6 : 1);
  flashlight.intensity = 105 * flicker;

  // souls
  const soul = world.tryCollectSoul(state.pos);
  if (soul) {
    state.collected++;
    updatePips();
    audio.pickup();
    if (state.collected >= CONFIG.soulsNeeded) {
      world.activateExit();
      audio.exitChime();
      ui.compass.classList.add('show');
      showHint('THE EXIT IS OPEN — RUN.', false, 4200);
    } else {
      showHint(`SOUL CLAIMED — ${state.collected} OF ${CONFIG.soulsNeeded}`, false, 2500);
    }
  }

  // exit gate
  const dxExit = state.pos.x - world.exit.pos.x;
  const dzExit = state.pos.z - world.exit.pos.z;
  const exitDist = Math.hypot(dxExit, dzExit);
  if (world.exitActive && exitDist < 1.55) {
    winRun();
  } else if (!world.exitActive && exitDist < 2.1 && state.elapsed - state.exitSealedAt > 5) {
    state.exitSealedAt = state.elapsed;
    showHint('SEALED — FIVE SOULS REQUIRED', true, 2400);
  }

  // compass
  if (world.exitActive) {
    const desired = Math.atan2(-(world.exit.pos.x - state.pos.x), -(world.exit.pos.z - state.pos.z));
    const rel = wrapAngle(desired - state.yaw);
    ui.compassArrow.style.transform = `rotate(${-rel}rad)`;
    ui.compassDist.textContent = `EXIT ${Math.round(exitDist)}m`;
  }

  // demon
  const sprintingForNoise = sprinting;
  demon.update(dt, state.visualTime, {
    mode: 'playing',
    grace: state.grace,
    world,
    playerPos: state.pos,
    sprinting: sprintingForNoise,
    flashlightOn: state.flashlightOn,
    onCatch: beginDeath,
    onGrowl: () => audio.growl(),
  });
  state.threat = demon.threat;

  // audio + ui
  const nearest = world.nearestSoulDistance(state.pos);
  audio.update(dt, state.threat, true, nearest);
  ui.threat.style.opacity = String(clamp(state.threat * 0.82, 0, 0.8));
  ui.stamina.style.width = `${state.stamina}%`;
  ui.stamina.classList.toggle('low', state.stamina < 22);

  const clockText = formatTime(state.elapsed);
  if (clockText !== state.lastClock) {
    state.lastClock = clockText;
    ui.clock.textContent = clockText;
  }

  if (state.hintUntil && performance.now() > state.hintUntil) {
    ui.hint.classList.remove('show');
    state.hintUntil = 0;
  }
}

function updateDying(dt) {
  state.visualTime += dt;
  state.deathT += dt;
  state.shake = Math.max(0, 1 - state.deathT * 0.8);

  const dx = demon.group.position.x - state.pos.x;
  const dz = demon.group.position.z - state.pos.z;
  state.yaw = Math.atan2(-dx, -dz);
  state.pitch = 0.32;
  const s = state.shake;
  const shakeX = (Math.random() - 0.5) * 0.09 * s;
  const shakeY = (Math.random() - 0.5) * 0.09 * s;
  camera.position.set(state.pos.x, CONFIG.eyeHeight + shakeY, state.pos.z);
  camera.rotation.set(state.pitch + (Math.random() - 0.5) * 0.04 * s, state.yaw + shakeX, (Math.random() - 0.5) * 0.06 * s);

  demon.update(dt, state.visualTime, {
    mode: 'dying',
    grace: 0,
    world,
    playerPos: state.pos,
    sprinting: false,
    flashlightOn: state.flashlightOn,
  });

  const pulse = 0.72 + Math.sin(state.deathT * 34) * 0.12;
  setFlash(pulse * clamp(1.2 - state.deathT * 0.35, 0.35, 1));
  audio.update(dt, 1, false);

  if (state.deathT > 1.55) finishDeath();
}

function updateIdle(dt) {
  state.visualTime += dt;
  demon.update(dt, state.visualTime, {
    mode: state.mode === 'paused' ? 'paused' : 'menu',
    grace: 99,
    world,
    playerPos: state.pos,
    sprinting: false,
    flashlightOn: state.flashlightOn,
  });
  if (state.mode === 'menu' || state.mode === 'paused') {
    camera.position.set(state.pos.x, CONFIG.eyeHeight, state.pos.z);
    camera.rotation.set(state.pitch, state.yaw, 0);
  }
  audio.update(dt, 0, false);
}

/* ---------------- main loop ---------------- */

function frame(now) {
  requestAnimationFrame(frame);
  let dt = (now - last) / 1000;
  last = now;
  if (!Number.isFinite(dt)) dt = 0;
  dt = Math.min(dt, 0.05);

  if (state.mode === 'playing') updatePlaying(dt);
  else if (state.mode === 'dying') updateDying(dt);
  else updateIdle(dt);

  world.update(dt, state.visualTime);
  renderer.render(scene, camera);
}

function onResize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, IS_MOBILE ? 1.6 : 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.fov = w / h < 0.8 ? 79 : 71;
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', onResize);
onResize();

/* ---------------- boot ---------------- */

layout = world.generate();
prepareRun(layout);
demon.update(0, 0, {
  mode: 'menu', grace: 99, world, playerPos: state.pos,
  sprinting: false, flashlightOn: true,
});
renderer.render(scene, camera);
requestAnimationFrame(frame);

setTimeout(() => ui.boot.classList.add('gone'), 120);
setTimeout(() => { ui.boot.style.display = 'none'; }, 1900);

// Small public debug surface for automated browser verification.
window.__SOUL_EYES__ = {
  state,
  world,
  demon,
  start: () => startRun(false),
  restart: restartRun,
  get mode() { return state.mode; },
};

