for (let i = 0; i < pos.count; i++) {
  v.fromBufferAttribute(pos, i);
  if (v.y < 0.46) {
    const a = Math.atan2(v.z, v.x);
    const ragged = 1 + Math.sin(a * 9 + 0.7) * 0.08 + Math.sin(a * 23) * 0.025;
    v.x *= ragged;
    v.z *= ragged;
    if (v.y < 0.09) v.y = Math.abs(Math.sin(a * 7)) * 0.12;
