```js
function updateCharacter(c, dt, t) {
  // if cooldown: stand, flash fade
  // else move along ellipse if not surging? always move; surge slows
  const speedFactor = c.surging ? .35 : 1;
  c.phase += dt * c.speed * speedFactor;
  const x = Math.cos(c.phase)*c.rx;
  const z = Math.sin(c.phase)*c.rz;
  const dx = -Math.sin(c.phase)*c.rx*c.speed; ...
  c.group.position.set(x, 0, z);
  c.group.rotation.y = Math.atan2(dx, dz); // face tangent +z
  // leg/arm swing
  const swing = Math.sin(t * (c.surging?16:9) + c.offset) * (c.surging?.18:.45);
  c.legL.rotation.x = swing; c.legR.rotation.x = -swing;
  c.armL.rotation.x = -swing*.8; c.armR.rotation.x = swing*.8;
  // size
  const targetSize = c.side==='boy' ? 1 - .3*c.intensity : 1 + .42*c.intensity;
  c.size = lerp(c.size,targetSize,1-exp(-6dt));
  c.group.scale.setScalar(c.baseScale * c.size);
  // glow
  c.jersey.emissiveIntensity = c.intensity*.9;
  c.glow.material.opacity = c.intensity*.35;
  // flash
  if (c.flash>0){ c.flash-=dt*1.6; c.flashSprite.material.opacity=clamp(c.flash,0,1); c.flashSprite.scale.setScalar(1+ (1-c.flash)*2); }
  else opacity 0;
}
