import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport:{width:1100,height:800} });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERR', e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/gym.html', { waitUntil:'load' });
await page.waitForTimeout(1500);
console.log('menu', await page.evaluate(() => ({
  mode: window.__GYM_SURGE__?.mode,
  low: window.__GYM_SURGE__?.lowGfx,
  gpu: window.__GYM_SURGE__?.gpuName,
  orbs: window.__GYM_SURGE__?.orbs.length,
  npcs: window.__GYM_SURGE__?.npcs.length,
  side: window.__GYM_SURGE__?.state.side,
})));
await page.screenshot({ path:'/tmp/opencode/gym-menu.png' });
await page.click('#startBtn');
await page.waitForTimeout(1200);
console.log('start', await page.evaluate(() => ({
  mode: __GYM_SURGE__.mode,
  charge: __GYM_SURGE__.state.charge,
  size: __GYM_SURGE__.state.size,
  elapsed: __GYM_SURGE__.state.elapsed,
  hud: !document.getElementById('hud').classList.contains('hidden'),
})));
await page.screenshot({ path:'/tmp/opencode/gym-start.png' });
await browser.close();
console.log('errors', errors);

