input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport:{width:960,height:720} });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERR', e.message); });
await page.goto('http://localhost:3002/gym.html', { waitUntil:'load' });
await page.waitForTimeout(800);
await page.click('[data-side="boy"]');
await page.click('#startBtn');
await page.waitForTimeout(600);
console.log('start boy', await page.evaluate(() => ({
  mode: __GYM_SURGE__.mode, side: __GYM_SURGE__.state.side,
  charge: +__GYM_SURGE__.state.charge.toFixed(1),
  size: +__GYM_SURGE__.state.size.toFixed(3),
})));
await page.keyboard.down('Space');
await page.waitForTimeout(1500);
console.log('surge 1.5s', await page.evaluate(() => ({
  charge: +__GYM_SURGE__.state.charge.toFixed(1),
  score: +__GYM_SURGE__.state.score.toFixed(2),
  intensity: +__GYM_SURGE__.state.intensity.toFixed(2),
  size: +__GYM_SURGE__.state.size.toFixed(3),
  hudHeight: document.getElementById('heightReadout').textContent,
})));
await page.screenshot({ path:'/tmp/opencode/gym-surge-boy.png' });
// hold until burnout
await page.waitForTimeout(2600);
console.log('after burnout', await page.evaluate(() => ({
  charge: +__GYM_SURGE__.state.charge.toFixed(1),
  burnouts: __GYM_SURGE__.state.burnouts,
  cooldown: +__GYM_SURGE__.state.cooldown.toFixed(2),
  lockout: __GYM_SURGE__.state.lockout,
  size: +__GYM_SURGE__.state.size.toFixed(2),
  label: document.getElementById('burnout').classList.contains('show'),
})));
await page.keyboard.up('Space');
await page.waitForTimeout(250);
console.log('released', await page.evaluate(() => ({ lockout: __GYM_SURGE__.state.lockout, holdActive: document.getElementById('holdBtn').classList.contains('active') })));
// collect an orb by teleporting onto one
const orbInfo = await page.evaluate(() => {
  const o = __GYM_SURGE__.orbs.find(o => o.userData.active);
  __GYM_SURGE__.state.charge = 20;
  __GYM_SURGE__.state.pos.set(o.position.x, 0, o.position.z);
  return { x:o.position.x, z:o.position.z, active:o.userData.active };
